"""版本号解析与比较。

Windows 产品的版本号习惯是 ``major.minor.build.revision`` 四段十进制，
末尾段可以省略（省略视作 0），并且允许 ``1.2.3.4-beta.1`` 这样的预发布标签。

比较规则：

* 数字段按**十进制整数**比较，而不是按字符串比较，因此 ``1.10.0`` 比
  ``1.9.0`` 新、``2.0.0`` 比 ``10.0.0`` 旧、``1.02`` 与 ``1.2`` 等价；
* 不足四段的右侧补 0，因此 ``1.2``、``1.2.0``、``1.2.0.0`` 互相等价；
* 数字部分相同时，带预发布标签的版本低于正式版：``1.0.0-beta`` < ``1.0.0``；
* 预发布标签内部按 ``.`` 分段比较：纯数字段按数值比较（``beta.10`` > ``beta.9``），
  纯数字段低于同位置的字母数字段，其余按字典序，段数少的一侧更低。
"""

_STRIP = "vV"
_DIGITS = "0123456789"
SEGMENTS = 4


def normalize(text):
    """去掉可选的 ``v`` 前缀与首尾空白。"""
    value = str(text).strip()
    while value[:1] in _STRIP:
        value = value[1:]
    return value


def split_version(text):
    """把版本号拆成 ``(数字部分, 预发布标签)``。"""
    value = normalize(text)
    if "+" in value:
        # ``1.0.0+build.5`` 里的构建元数据不参与比较
        value = value.split("+", 1)[0]
    if "-" in value:
        numbers, prerelease = value.split("-", 1)
    else:
        numbers, prerelease = value, ""
    return numbers, prerelease.strip()


def _decimal(segment):
    """把一段版本号解释成十进制整数。

    无法完整解释时退回前导数字，完全没有数字则为 0。这样 ``1.02`` 与 ``1.2``
    等价，遇到古怪的段也不会让比较直接崩溃。
    """
    text = str(segment).strip()
    if not text:
        return 0
    negative = text[0] == "-"
    if negative:
        text = text[1:]
    digits = ""
    for ch in text:
        if ch not in _DIGITS:
            break
        digits += ch
    if not digits:
        return 0
    value = int(digits, 10)
    return -value if negative else value


def _is_decimal(segment):
    """一段标识符是否是纯十进制数字。"""
    text = str(segment).strip()
    return bool(text) and all(ch in _DIGITS for ch in text)


def _numeric_segments(numbers):
    """把点分数字部分解释成整数段，不足四段的右侧补 0。"""
    segments = [_decimal(part) for part in numbers.split(".")]
    while len(segments) < SEGMENTS:
        segments.append(0)
    return segments


def parse_version(text):
    """把版本号拆成段列表。

    段之间用 ``.`` 分隔，每段解释成**十进制整数**；不足四段的右侧补 0，
    因此 ``parse_version("1.2") == parse_version("1.2.0") == [1, 2, 0, 0]``。
    预发布标签不包含在结果里（用 :func:`split_version` 单独取）。
    """
    numbers, _prerelease = split_version(text)
    return _numeric_segments(numbers)


def _compare_segments(left, right):
    """逐段比较两个整数段列表；短的一侧视作右侧补 0。"""
    width = max(len(left), len(right))
    for index in range(width):
        one = left[index] if index < len(left) else 0
        two = right[index] if index < len(right) else 0
        if one != two:
            return -1 if one < two else 1
    return 0


def _compare_prerelease(left, right):
    """比较两个预发布标签。"""
    left_ids = left.split(".") if left else []
    right_ids = right.split(".") if right else []
    for one, two in zip(left_ids, right_ids):
        one_num, two_num = _is_decimal(one), _is_decimal(two)
        if one_num and two_num:
            if int(one, 10) != int(two, 10):
                return -1 if int(one, 10) < int(two, 10) else 1
        elif one_num != two_num:
            # 纯数字标识符总是低于字母数字标识符
            return -1 if one_num else 1
        elif one != two:
            return -1 if one < two else 1
    if len(left_ids) != len(right_ids):
        return -1 if len(left_ids) < len(right_ids) else 1
    return 0


def compare_versions(left, right):
    """比较两个版本号。

    返回 ``-1`` / ``0`` / ``1``。数字段按十进制数值比较、不足四段补 0；
    预发布版本低于同号的正式版。
    """
    left_numbers, left_pre = split_version(left)
    right_numbers, right_pre = split_version(right)
    order = _compare_segments(_numeric_segments(left_numbers),
                              _numeric_segments(right_numbers))
    if order:
        return order
    if left_pre == right_pre:
        return 0
    if not left_pre:
        return 1
    if not right_pre:
        return -1
    return _compare_prerelease(left_pre, right_pre)


def is_upgrade(current, candidate):
    """``candidate`` 是否严格高于 ``current``。"""
    return compare_versions(candidate, current) > 0

